// Validate and prepare jobs for ingestion
const input = $input.first().json.body;
const jobs = input.jobs || [];

if (!Array.isArray(jobs) || jobs.length === 0) {
  throw new Error('No jobs provided for ingestion');
}

// Validate each job has required fields
const validatedJobs = jobs.map((job, index) => {
  if (!job.title) {
    throw new Error(`Job at index ${index} missing required field: title`);
  }
  return {
    title: job.title,
    company: job.company || 'Unknown',
    location: job.location || '',
    clearance: job.clearance || '',
    description: job.description || '',
    url: job.url || '',
    source: job.source || 'n8n-ingest',
    scraped_at: job.scraped_at || new Date().toISOString()
  };
});

return {
  json: {
    jobs: validatedJobs,
    count: validatedJobs.length
  }
};

// Format response
const hubResponse = $input.first().json;
const inputData = $('Validate Jobs').first().json;

return {
  json: {
    success: true,
    message: `Ingested ${inputData.count} jobs to Hub`,
    hub_response: hubResponse,
    timestamp: new Date().toISOString()
  }
};
